      "rank": 1,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement and provide an exceptionally clear new instrument for testing physics and redefining timekeeping.",
        "attribution": "Katori pioneered the lattice-clock concept and Ye made decisive experimental advances toward its highest performance.",
        "maturity": "The method has been independently reproduced, steadily improved, and has reached a level where broad scientific and metrological impact is unmistakable.",
        "uncertainties": [
          "The eventual scope of a prize would need to distinguish the central lattice-clock invention from wider optical-clock development."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry made quantum coherence into an unusually powerful practical measuring tool, with fundamental and applied consequences.",
        "attribution": "Bordé supplied foundational interferometric ideas, while Pritchard and Kasevich were central to its experimental development and precision applications.",
        "maturity": "The technique is long established across laboratories and supports highly sensitive inertial, gravitational, and fundamental-physics measurements.",
        "uncertainties": [
          "Credit boundaries are broad because atom interferometry emerged through several closely related experimental traditions."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent optical control of diamond spins created a versatile solid-state platform for quantum sensing and quantum science.",
        "attribution": "Jelezko and Wrachtrup established key single-spin optical-control experiments, with Lukin making major contributions to the field's quantum-information development.",
        "maturity": "The experimental platform is reproducible, widely used, and has demonstrated sensing capabilities beyond a single proof-of-principle experiment.",
        "uncertainties": [
          "Attribution must separate the core diamond-spin breakthroughs from the much larger subsequent sensing community."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire and passive mode-locking made reliable ultrashort pulses broadly available and enabled a vast range of optical measurement methods.",
        "attribution": "Moulton's laser medium and Keller's and Sibbett's pioneering mode-locking work identify a coherent core of credit.",
        "maturity": "The technology has had decades of deep scientific use and continues to underpin ultrafast spectroscopy and strong-field science.",
        "uncertainties": [
          "Ultrafast laser development contains many important contributors, so the precise formulation of the award would be consequential."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the conceptual route by which fragile quantum coherence could support scalable computation.",
        "attribution": "Shor and Steane introduced seminal code constructions, while Kitaev provided fundamental topological fault-tolerance concepts.",
        "maturity": "The principles are experimentally influential and central to present quantum hardware, though full fault-tolerant computation remains incomplete.",
        "uncertainties": [
          "The ultimate practical threshold and scale of fault-tolerant quantum computing have not yet been established."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B027",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band-gap concepts changed the understanding and engineering of light propagation in structured media.",
        "attribution": "John and Yablonovitch formulated and demonstrated central photonic-crystal ideas, with Joannopoulos providing essential theoretical development.",
        "maturity": "Photonic crystals are a durable and widely implemented optical platform with influence across nanophotonics and quantum optics.",
        "uncertainties": [
          "Applications are diverse, making it important to preserve the distinction between the foundational band-gap discovery and later device work."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics brought strong, controllable light-matter interaction into superconducting circuits and made a major quantum platform experimentally accessible.",
        "attribution": "Blais developed the defining theoretical framework, and Wallraff and Schoelkopf led landmark experimental realization; Girvin's theoretical role is also substantial.",
        "maturity": "The architecture is extensively reproduced and forms a principal route toward quantum processors and quantum-limited measurements.",
        "uncertainties": [
          "A three-person limit makes complete attribution difficult, particularly regarding foundational theoretical contributions."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B039",
      "proposed_laureates": [
        "David DeMille",
        "John M. Doyle",
        "Michael R. Tarbutt"
      ],
      "assessment": {
        "nobel_worthiness": "Laser cooling and trapping of molecules opened a qualitatively new regime for molecular precision measurement, collisions, and quantum control.",
        "attribution": "DeMille, Doyle, and Tarbutt represent key experimental advances that made direct molecular laser cooling viable.",
        "maturity": "The experiments have been reproduced and extended to multiple molecular species, with a growing range of precision and many-body applications.",
        "uncertainties": [
          "The field remains younger than atomic laser cooling, and its eventual breadth and applications are still developing."
        ]
      }
    }
  ]
